import ctypes, os
import numpy as np
K, KC = 20, 30

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "lap.so"))
_lib.solve_lap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_void_p]
_lib.solve_lap.restype = ctypes.c_int


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = problem["cost_matrix"]
        n = a.shape[0]
        if (n == 0 or b.shape[0] != n or not np.all(a == a[0]) or not np.all(b == a[0])):
            return {"transport_plan": _fallback(a, b, M)}
        Mc = np.ascontiguousarray(M, dtype=np.float64)
        c4r = np.empty(n, dtype=np.int32)
        ret = _lib.solve_lap(n, Mc.ctypes.data, K, KC, c4r.ctypes.data)
        if ret != 0:
            return {"transport_plan": _fallback(a, b, M)}
        G = np.zeros((n, n))
        G[np.arange(n), c4r] = a[0]
        return {"transport_plan": G}

