#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdio.h>
#include <time.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec*1e-9;}
typedef struct {double d; int j;} HE;
static inline void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)/2;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static inline HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}if(n>0)h[i]=last;return top;}

static double qsel(double*a,int n,int k){ /* k-th smallest (0-based) */
  int l=0,r=n-1;
  while(l<r){double p=a[(l+r)>>1];int i=l,j=r;
    while(i<=j){while(a[i]<p)i++;while(a[j]>p)j--;if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}
    if(k<=j)r=j;else if(k>=i)l=i;else return a[k];}
  return a[k];
}

